<?php namespace App\Policies;use App\Models\{FulfilmentOrder,User};final class FulfilmentOrderPolicy{public function view(User$u,FulfilmentOrder$o):bool{return $u->tenantMemberships()->where('tenant_id',$o->tenant_id)->where('status','ACTIVE')->exists();}public function update(User$u,FulfilmentOrder$o):bool{return $this->view($u,$o)&&$u->tenantMemberships()->where('tenant_id',$o->tenant_id)->whereIn('role',['TENANT_ADMIN','OPERATIONS'])->exists();}}
